{
  "name": "QuTech双工器",
  "name_en": "QuTech Duplexer",
  "manufacturer": "TNO",
  "description": "这是一台用于微波实验的多通道双工器，可对通道开关状态、相位和衰减进行统一设置，并支持与衰减标定相关的计算。",
  "description_en": "A multi-channel duplexer for microwave experiments, supporting bulk control of switch states, phase, and attenuation, as well as attenuation-related scaling calculations.",
  "actions": [
    {
      "action_name": "auto-add_parameters",
      "description": "定义多组通道参数。",
      "description_en": "Define multiple channel parameters."
    },
    {
      "action_name": "auto-calculate_attenuation",
      "description": "根据当前DAC值和缩放因子计算衰减值。",
      "description_en": "Calculate attenuation from the current DAC value and scaling factor."
    },
    {
      "action_name": "auto-set_all_attenuations_to",
      "description": "将所有通道的衰减设置为指定值。",
      "description_en": "Set the attenuation of all channels to a specified value."
    },
    {
      "action_name": "auto-set_all_phases_to",
      "description": "将所有通道的相位设置为指定值。",
      "description_en": "Set the phase of all channels to a specified value."
    },
    {
      "action_name": "auto-set_all_switches_to",
      "description": "将所有开关设置为指定模式。",
      "description_en": "Set all switches to a specified mode."
    },
    {
      "action_name": "auto-get_scaling_increment",
      "description": "获取缩放增量。",
      "description_en": "Get the scaling increment."
    },
    {
      "action_name": "auto-add_parameter",
      "description": "定义单个设备参数。",
      "description_en": "Define a single device parameter."
    }
  ],
  "tag_hints": [
    "microwave duplexer",
    "RF switching",
    "phase control",
    "attenuation control",
    "multi-channel microwave routing",
    "DAC-based attenuation scaling",
    "VISA instrument"
  ]
}

